.vc-reviews-pager{
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  margin: 18px 0 14px;
}


.vc-reviews-pager__meta{
  font-size: 0.9rem;
  opacity: 0.9;
}


.vc-reviews-pager__bar{
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 14px;
  width: 100%;
  padding: 12px 16px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(12, 10, 8, 0.55);
  box-sizing: border-box;
}


.vc-reviews-pager__bar--simple{
  justify-content: center;
}


.vc-reviews-pager__meta--stats{
  flex: 1 1 12rem;
  text-align: center;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: rgba(226, 232, 240, 0.92);
  opacity: 1;
  min-width: 0;
}


.vc-reviews-pager__btn{
  flex: 0 0 auto;
  min-width: 7.25rem;
}


html{
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: #6b4e3d #140f0c;
  min-height: 100%;
  /* 20260907cursorFix2: vinyl ← musicrecordspin.gif scaled ~24px, transparent GIF only */
  cursor: var(--vc-cursor-default); /* 20260913cursorStatic1 */
}


body{
  margin: 0;
  min-height: 100%;
  cursor: inherit;
}


.vc-cursor-trail{
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  inset: auto;
  width: 100vw !important;
  height: 100vh !important;
  pointer-events: none !important;
  z-index: 2147483645 !important;
  display: block !important;
  overflow: visible !important;
}


html.vc-type-sfx-off .vc-type-sfx-player{
  display: none !important;
}


.vc-type-sfx-player[hidden]{
  display: none !important;
}


input[type="text"]:not(:disabled),
input[type="search"]:not(:disabled),
input[type="email"]:not(:disabled),
input[type="password"]:not(:disabled),
input[type="url"]:not(:disabled),
input[type="tel"]:not(:disabled),
input[type="number"]:not(:disabled),
input:not([type]):not(:disabled),
textarea:not(:disabled),
[contenteditable="true"]{
  cursor: text;
}


button:disabled,
[disabled],
[aria-disabled="true"]{
  cursor: not-allowed;
}


html::-webkit-scrollbar{
  width: 11px;
  height: 11px;
}


html::-webkit-scrollbar-track{
  background: linear-gradient(180deg, #140f0c 0%, #0a0806 100%);
  border-radius: 999px;
}


html::-webkit-scrollbar-thumb{
  background: linear-gradient(180deg, #7a5a45 0%, #4a3428 55%, #3d2a1f 100%);
  border-radius: 999px;
  border: 2px solid #0f0b09;
  box-shadow: inset 0 1px 0 rgba(212, 181, 152, 0.22);
}


html::-webkit-scrollbar-thumb:hover{
  background: linear-gradient(180deg, #8f6b52 0%, #5c4033 100%);
}


.vc-body{
  position: relative;
  min-height: 100vh;
  color: #ebe0d6;
  background-color: #080605;
  background-image:
    radial-gradient(ellipse 90% 70% at 92% 8%, rgba(var(--vc-sand-rgb), 0.1), transparent 52%),
    radial-gradient(ellipse 130% 95% at 50% -8%, rgba(130, 78, 48, 0.34), transparent 62%),
    radial-gradient(ellipse 100% 75% at 100% 32%, rgba(var(--vc-mocha-rgb), 0.22), transparent 56%),
    radial-gradient(ellipse 90% 70% at 0% 68%, rgba(48, 32, 22, 0.26), transparent 58%),
    linear-gradient(180deg, #0a0d10 0%, #100b08 18%, #15100c 38%, #120d0a 55%, #0e0a07 78%, #080605 100%);
  background-attachment: scroll;
  background-repeat: no-repeat;
}


.vc-body::before{
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 85% 70% at 50% 0%, rgba(var(--vc-mocha-rgb), 0.22), transparent 55%);
  mix-blend-mode: normal;
  opacity: 0.85;
}


.vc-body::after{
  content: "";
  position: fixed;
