    0 18px 38px rgba(0, 0, 0, 0.48),
    0 0 0 1px rgba(var(--vc-reviews-emerald-rgb), 0.08) inset,
    0 0 28px rgba(var(--vc-reviews-glow-rgb), 0.12);
  pointer-events: none;
  opacity: 0;
  transition:
    opacity 0.2s ease,
    transform 0.2s ease;
}


.discord-profile-hover::before{
  content: "";
  position: absolute;
  left: 50%;
  top: -0.36rem;
  width: 0.72rem;
  height: 0.72rem;
  transform: translateX(-50%) rotate(45deg);
  border-left: 1px solid rgba(110, 231, 183, 0.32);
  border-top: 1px solid rgba(110, 231, 183, 0.32);
  background: rgba(12, 24, 22, 0.98);
}


.discord-profile-link::after{
  content: "";
  position: absolute;
  inset: -3px;
  z-index: 2;
  border-radius: inherit;
  border: 2px solid rgba(var(--vc-sand-rgb), 0.55);
  box-shadow:
    0 0 0 3px rgba(var(--vc-mocha-rgb), 0.18),
    0 0 18px rgba(var(--vc-sand-rgb), 0.32),
