  filter: drop-shadow(0 0 10px rgba(212, 175, 55, 0.42));
  animation: vc-forbidden-book-float 2.7s ease-in-out infinite;
  transition: filter 0.18s ease, opacity 0.18s ease, transform 0.18s ease;
}


.vc-forbidden-book[hidden],
.vc-forbidden-book:not(.vc-forbidden-book--flying){
  /* cssFoucKill1: mai 📖 in-title — solo stato flying (caccia) è visibile */
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
  font-size: 0 !important;
  width: 0 !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
}


.vc-forbidden-book--flying{
  display: inline-block !important;
  visibility: visible !important;
  opacity: 1 !important;
  pointer-events: auto !important;
  font-size: clamp(2.1rem, 5vw, 4.2rem) !important;
  width: auto !important;
  height: auto !important;
  overflow: visible !important;
  position: fixed;
  left: 50%;
  top: 42%;
  z-index: 2147483000;
  margin: 0;
  padding: 0.16em 0.22em;
  min-width: 2.85rem;
  min-height: 2.85rem;
  line-height: 1;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  text-shadow: 0 0 14px rgba(255, 246, 200, 0.65);
  transform: translate(-50%, -50%) rotate(var(--vc-book-rotate, -6deg));
  transition: left 0.72s cubic-bezier(0.26, 1.42, 0.4, 1), top 0.72s cubic-bezier(0.26, 1.42, 0.4, 1), filter 0.16s ease, opacity 0.16s ease, transform 0.16s ease;
  animation: vc-forbidden-book-flap 0.42s ease-in-out infinite alternate;
}


.vc-forbidden-book:hover,
.vc-forbidden-book:focus-visible{
  outline: none;
  filter: drop-shadow(0 0 18px rgba(248, 231, 162, 0.86));
  transform: translate(-50%, -50%) rotate(var(--vc-book-rotate, 5deg)) scale(1.16);
}


.vc-forbidden-book--caught{
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -50%) rotate(var(--vc-book-rotate, 0deg)) scale(0.2);
}


.vc-forbidden-book-toast{
  position: fixed;
  left: 50%;
  right: auto;
  bottom: calc(1.15rem + env(safe-area-inset-bottom, 0px));
  transform: translateX(-50%) translateY(0.7rem);
  z-index: 10150;
  width: min(92vw, 22rem);
  max-width: min(22rem, calc(100vw - 2rem));
  border: 1px solid rgba(110, 231, 183, 0.42);
  border-radius: 0.95rem;
  padding: 0.7rem 0.95rem;
  color: rgba(241, 245, 249, 0.94);
  background: linear-gradient(145deg, rgba(16, 24, 20, 0.96), rgba(12, 40, 32, 0.92));
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.45);
  font-size: 0.88rem;
  font-weight: 700;
  text-align: left;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
}


.vc-forbidden-book-toast--show{
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}


@keyframes vc-forbidden-book-float{
  0%,
  100% {
    transform: translateY(0) rotate(-3deg);
  }

  50% {
    transform: translateY(-0.35em) rotate(4deg);
  }
}


