  position: relative;
  width: min(12rem, 94%);
  height: 24rem;
  margin: 0.65rem auto 0.9rem;
}


.vc-hw-hourglass__cap{
  position: absolute;
  left: 4%;
  z-index: 3;
  width: 92%;
  height: 1.15rem;
  border-radius: 999px;
  background: linear-gradient(180deg, #f9e6a1, #b7792f 50%, #593515);
  box-shadow: 0 5px 18px rgba(0, 0, 0, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.44);
}


.vc-hw-hourglass__cap--top{
  top: 0;
}


.vc-hw-hourglass__cap--bottom{
  bottom: 0;
}


.vc-hw-hourglass__bulb{
  position: absolute;
  left: 11%;
  width: 78%;
  height: 11.1rem;
  border: 2px solid rgba(255, 231, 166, 0.42);
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.03) 26%, rgba(255, 255, 255, 0.08) 72%, rgba(255, 255, 255, 0.18));
  overflow: hidden;
  box-shadow: inset 0 0 30px rgba(255, 255, 255, 0.08), 0 0 28px color-mix(in srgb, var(--house-color) 22%, transparent);
}


.vc-hw-hourglass__bulb--top{
  top: 0.65rem;
  border-radius: 48% 48% 42% 42% / 16% 16% 74% 74%;
}


.vc-hw-hourglass__bulb--bottom{
  bottom: 0.65rem;
  border-radius: 42% 42% 48% 48% / 74% 74% 16% 16%;
}


.vc-hw-hourglass__sand{
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  background: radial-gradient(circle at 28% 18%, rgba(255, 255, 255, 0.95) 0 1px, transparent 2px),
    radial-gradient(circle at 70% 38%, rgba(255, 255, 255, 0.82) 0 1px, transparent 2px),
    radial-gradient(circle at 48% 68%, rgba(255, 255, 255, 0.74) 0 1px, transparent 2px),
    linear-gradient(180deg, color-mix(in srgb, var(--house-accent) 55%, #fff 18%), var(--house-color));
  background-size: 18px 18px, 22px 22px, 16px 16px, auto;
  box-shadow: inset 0 8px 16px rgba(255, 255, 255, 0.16), 0 -6px 22px color-mix(in srgb, var(--house-color) 55%, transparent);
  transition: height 3.4s cubic-bezier(0.18, 0.72, 0.22, 1);
}


.vc-hw-hourglass__sand--top{
  height: var(--top-fill);
  opacity: 0.82;
  transition: height 3.4s cubic-bezier(0.18, 0.72, 0.22, 1);
}


.vc-hw-hourglass__sand--bottom{
  height: var(--fill);
}


.vc-hw-hourglass__stream{
  position: absolute;
  left: 50%;
  top: 46%;
  z-index: 5;
  width: 0.34rem;
  height: 3.9rem;
  transform: translate(-50%, -50%);
  border-radius: 999px;
  background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--house-accent) 72%, #fff 22%), var(--house-color), transparent);
  filter: drop-shadow(0 0 10px color-mix(in srgb, var(--house-color) 80%, transparent));
  opacity: 0;
}


.vc-hw-hourglass__stream::before,
.vc-hw-hourglass__stream::after{
  content: "";
  position: absolute;
  inset: -0.55rem -0.42rem;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.9) 0 1px, transparent 1.7px);
  background-size: 9px 9px;
  opacity: 0;
}


.vc-hw-hourglass__stream::after{
  opacity: 0.55;
}


.vc-hw-hourglass--pouring .vc-hw-hourglass__stream{
