.vc-hw-bgm-hint{
  position: fixed;
  right: 1.1rem;
  bottom: calc(1.1rem + 4.6rem + 0.55rem);
  z-index: 100520;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  max-width: min(15.5rem, calc(100vw - 2.2rem));
  margin: 0;
  padding: 0.42rem 0.72rem 0.42rem 0.48rem;
  border-radius: 999px;
  border: 1px solid rgba(212, 168, 120, 0.28);
  background: rgba(18, 12, 9, 0.78);
  backdrop-filter: blur(var(--vc-glass-blur)) saturate(140%);
  -webkit-backdrop-filter: blur(var(--vc-glass-blur)) saturate(140%);
  color: rgba(247, 236, 223, 0.92);
  font-family: inherit;
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  line-height: 1.25;
  text-align: left;
  box-shadow:
    0 8px 22px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  pointer-events: auto;
