.vc-tprof-panel{
  position: relative;
  display: flex;
  overflow: hidden;
  border-radius: 1.1rem;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background:
    linear-gradient(165deg, rgba(34, 24, 18, 0.96), rgba(16, 12, 10, 0.98));
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.28);
}


.vc-tprof-panel__accent{
  flex: 0 0 0.3rem;
  background: linear-gradient(180deg, #e8c9a8, #6f4e37);
}


.vc-tprof-panel__body{
  flex: 1 1 auto;
  min-width: 0;
  padding: 1rem 1.05rem 1.05rem;
}


.vc-tprof-identity{
  display: flex;
  align-items: center;
  gap: 0.85rem;
  margin-bottom: 0.95rem;
  padding-bottom: 0.9rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}


.vc-tprof-identity__text{
  min-width: 0;
}


.vc-tprof-identity__name{
  margin: 0;
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #fff8f0;
  line-height: 1.2;
  word-break: break-word;
}


.vc-tprof-identity__id{
  margin: 0.28rem 0 0;
  font-size: 0.78rem;
  color: rgba(203, 213, 225, 0.78);
}


.vc-tprof-identity__id code{
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.76rem;
  color: rgba(232, 201, 168, 0.92);
}


.vc-tprof-identity__line{
  margin: 0 0 0.35rem;
  font-size: 0.92rem;
  color: rgba(248, 250, 252, 0.92);
  line-height: 1.35;
}


.vc-tprof-k{
  color: #e8c9a8;
  font-weight: 700;
}


.vc-tprof-thumb-wrap{
  position: relative;
  width: 4.25rem;
  height: 4.25rem;
  flex-shrink: 0;
}


.vc-tprof-thumb-wrap .vc-tprof-thumb--fb{
  display: none;
}


.vc-tprof-thumb-wrap.is-fallback .vc-tprof-thumb--fb,
.vc-tprof-thumb-wrap:not(:has(img)) .vc-tprof-thumb--fb{
  display: inline-flex;
}


.vc-tprof-thumb{
  width: 4.25rem;
  height: 4.25rem;
  border-radius: 1rem;
  object-fit: cover;
  border: 1px solid rgba(var(--vc-sand-rgb), 0.4);
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.04);
}


.vc-tprof-thumb--fb{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.06);
  color: #e8c9a8;
  font-size: 1.25rem;
}


.vc-tprof-stats{
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
}


.vc-tprof-stat{
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  min-height: 4.1rem;
  padding: 0.7rem 0.75rem;
  border-radius: 0.8rem;
  background: rgba(0, 0, 0, 0.24);
  border: 1px solid rgba(255, 255, 255, 0.06);
}


.vc-tprof-stat__label{
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(174, 182, 196, 0.95);
}


.vc-tprof-stat__value{
  color: #f8fafc;
  font-size: 1.15rem;
  font-weight: 800;
  line-height: 1.15;
}


.vc-tprof-stat__value--badges{
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  min-height: 1.4rem;
}


.vc-tprof-stat__empty{
  color: rgba(148, 163, 184, 0.9);
  font-weight: 700;
}


.vc-tprof-cols{
  display: grid;
  gap: 0.85rem;
}


.vc-tprof-list{
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}


.vc-tprof-list li{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.55rem 0.7rem;
  border-radius: 0.7rem;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.05);
}


.vc-tprof-list span{
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #aeb6c4;
}


.vc-tprof-list strong{
  color: #f8fafc;
  font-size: 0.95rem;
}


.vc-tprof-list__badges{
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}


.vc-tprof-section-head{
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.95rem;
}


.vc-tprof-section-head h2{
  margin: 0;
  font-size: 1.05rem;
  color: #fff8f0;
}


.vc-tprof-section-head p{
  margin: 0.25rem 0 0;
  font-size: 0.82rem;
  color: #94a3b8;
}


.vc-tprof-empty,
.vc-tprof-sub{
  color: #94a3b8;
  font-size: 0.86rem;
}


.vc-tprof-sub{
  margin: 0.95rem 0 0.45rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 0.7rem;
  color: #aeb6c4;
}


.vc-tprof-pager{
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  flex-shrink: 0;
}


.vc-tprof-pager__btn{
  width: 2rem;
  height: 2rem;
  border-radius: 0.55rem;
  border: 1px solid rgba(var(--vc-sand-rgb), 0.28);
  background: rgba(var(--vc-mocha-rgb), 0.4);
  color: #ead4c0;
  cursor: var(--vc-cursor-pointer);
}


.vc-tprof-pager__btn:disabled{
  opacity: 0.35;
  cursor: default;
}


.vc-tprof-pager__label{
  min-width: 3.2rem;
  text-align: center;
  font-size: 0.78rem;
  font-weight: 700;
  color: #cbd5e1;
}


.vc-tprof-obj-list{
  display: grid;
  gap: 0.7rem;
}


.vc-tprof-obj{
  display: flex;
  gap: 0.75rem;
  padding: 0.75rem;
  border-radius: 0.85rem;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(0, 0, 0, 0.2);
}


.vc-tprof-obj.is-done{
  border-color: rgba(var(--vc-sand-rgb), 0.28);
  background: rgba(var(--vc-mocha-rgb), 0.22);
}


.vc-tprof-obj__ico{
  flex-shrink: 0;
  width: 2.4rem;
  display: flex;
  justify-content: center;
  padding-top: 0.1rem;
}


.vc-tprof-obj__main{
  min-width: 0;
  flex: 1;
}


.vc-tprof-obj__main strong{
  color: #f8fafc;
  font-size: 0.92rem;
}


.vc-tprof-obj__main p{
  margin: 0.2rem 0 0;
  color: #94a3b8;
  font-size: 0.82rem;
  line-height: 1.4;
}


.vc-tprof-obj__bar{
  margin-top: 0.55rem;
  height: 0.32rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}


.vc-tprof-obj__bar span{
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #e8c9a8, #927048);
}


.vc-tprof-obj__meta{
  display: inline-block;
  margin-top: 0.35rem;
  font-size: 0.74rem;
  color: #aeb6c4;
}


.vc-tprof-slots{
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}


.vc-tprof-slot{
  width: 3rem;
  height: 3rem;
  border-radius: 0.8rem;
  border: 1px solid rgba(var(--vc-sand-rgb), 0.32);
  background: rgba(var(--vc-mocha-rgb), 0.35);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #e8c9a8;
  cursor: var(--vc-cursor-pointer);
}


.vc-tprof-slot.is-empty{
  opacity: 0.45;
  cursor: default;
}


.vc-tprof-badge-grid{
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(2.85rem, 1fr));
  gap: 0.4rem;
}


.vc-tprof-badge{
  aspect-ratio: 1;
  border-radius: 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: var(--vc-cursor-pointer);
}


.vc-tprof-badge.is-selected{
  border-color: rgba(var(--vc-sand-rgb), 0.55);
  background: rgba(var(--vc-mocha-rgb), 0.5);
}


.vc-tprof-badge.is-locked{
  opacity: 0.32;
  cursor: not-allowed;
}


.vc-tprof-setting{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.85rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}


.vc-tprof-setting strong{
  display: block;
  color: #f8fafc;
  font-size: 0.92rem;
}


.vc-tprof-setting p{
  margin: 0.2rem 0 0;
  color: #94a3b8;
  font-size: 0.8rem;
  line-height: 1.4;
}


.vc-tprof-lang{
  padding-top: 0.95rem;
}


.vc-tprof-lang strong{
  color: #f8fafc;
}


.vc-tprof-lang > p{
  margin: 0.25rem 0 0.75rem;
  color: #94a3b8;
  font-size: 0.82rem;
}


.vc-tprof-lang__grid{
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.4rem;
  width: 100%;
  overflow-x: auto;
  padding-bottom: 0.15rem;
}


.vc-tprof-lang__btn{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 1 1 0;
  min-width: 2.35rem;
  min-height: 2.55rem;
  padding: 0.4rem 0.25rem;
  border-radius: 0.7rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  color: #f8fafc;
  cursor: var(--vc-cursor-pointer);
}


.vc-tprof-lang__flag{
  display: block;
  width: 1.55rem;
  height: 1.15rem;
  border-radius: 0.18rem;
  object-fit: cover;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.22);
}


.vc-tprof-lang__btn.is-active,
.vc-tprof-lang__btn:hover{
  border-color: rgba(var(--vc-sand-rgb), 0.4);
  background: rgba(var(--vc-mocha-rgb), 0.42);
}


.vc-tprof-emoji{
  object-fit: contain;
  vertical-align: middle;
}


.vc-tprof-emoji-text{
  line-height: 1;
}


.vc-acc{
  display: grid;
  gap: 1.25rem;
  width: 100%;
}


.vc-acc-plans{
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  width: 100%;
  align-items: stretch;
}


.vc-acc-card,
.vc-acc-plan,
.vc-acc-section,
.vc-acc-hero{
  border-radius: 1.15rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(18, 13, 10, 0.72);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.28);
  padding: 1.25rem 1.35rem;
  min-width: 0;
}


.vc-acc-plan{
  display: flex;
  flex-direction: column;
  height: 100%;
}


.vc-acc-card__title,
.vc-acc-hero__title,
.vc-acc-section__title,
.vc-acc-plan__title{
  margin: 0;
  color: #f7ecdf;
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}


.vc-acc-card__text,
.vc-acc-hero__text,
.vc-acc-section__text,
.vc-acc-plan__sub{
  margin: 0.55rem 0 0;
  color: rgba(232, 201, 168, 0.78);
  font-size: 0.95rem;
  line-height: 1.5;
}


.vc-acc-card__text a,
.vc-acc-hero__text a{
  color: #e8c9a8;
  text-decoration: underline;
  text-underline-offset: 0.15em;
}


.vc-acc-card__actions,
.vc-acc-hero__actions,
.vc-acc-section__actions{
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin-top: 1.15rem;
}


.vc-gdpr-confirm-field{
  margin-top: 1.15rem;
  max-width: 22rem;
}


.vc-gdpr-confirm-field input{
  color-scheme: dark;
  color: #f7ecdf;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(245, 214, 183, 0.28);
}


.vc-gdpr-confirm-field input::placeholder{
  color: rgba(232, 201, 168, 0.78);
  -webkit-text-fill-color: rgba(232, 201, 168, 0.78);
  opacity: 1;
}


.vc-gdpr-count-block{
  margin-top: 1rem;
}


.vc-gdpr-count-block__title{
  margin: 0 0 0.45rem;
  font-size: 0.92rem;
  font-weight: 700;
  color: #e8c9a8;
}


.vc-gdpr-count-empty{
  margin: 0;
  color: #94a3b8;
  font-size: 0.88rem;
}


.vc-gdpr-count-list{
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}


.vc-gdpr-count-list li{
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.2rem 0.75rem;
  padding: 0.55rem 0.7rem;
  border-radius: 0.7rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.22);
  font-size: 0.88rem;
}


.vc-gdpr-count-list__label{
  color: #e2e8f0;
}


.vc-gdpr-count-list__n{
  font-weight: 700;
  color: #f8fafc;
}


.vc-gdpr-count-list__detail{
  grid-column: 1 / -1;
  color: #94a3b8;
  font-size: 0.8rem;
}


.vc-dati-status{
  margin: 0 auto 1rem;
  max-width: 40rem;
  padding: 0.75rem 1rem;
  border-radius: 0.85rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(0, 0, 0, 0.28);
  color: #e2e8f0;
  font-size: 0.92rem;
  text-align: center;
}


.vc-dati-status.is-error{
  border-color: rgba(220, 80, 80, 0.4);
  color: #fecaca;
}


.vc-dati-status.is-ok{
  border-color: rgba(100, 180, 120, 0.4);
  color: #bbf7d0;
}


.vc-dati-actions{
  display: grid;
  gap: 0.95rem;
  margin-top: 0;
}


.vc-dati-actions[hidden]{
  display: none !important;
}


body.vc-dati-page .vc-gdpr-confirm-field{
  display: grid;
  gap: 0.45rem;
  max-width: 24rem;
}


body.vc-dati-page .vc-gdpr-confirm-field span{
  color: rgba(232, 201, 168, 0.88);
  font-size: 0.92rem;
}


body.vc-dati-page .vc-gdpr-confirm-field input,
body.vc-dati-page #vc-gdpr-confirm-token{
  color: #f7ecdf;
  -webkit-text-fill-color: #f7ecdf;
  background: rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(245, 214, 183, 0.32);
}


body.vc-dati-page .vc-gdpr-confirm-field input::placeholder,
body.vc-dati-page #vc-gdpr-confirm-token::placeholder{
  color: rgba(232, 201, 168, 0.82);
  -webkit-text-fill-color: rgba(232, 201, 168, 0.82);
  opacity: 1;
}


.vc-acc-tier-list,
.vc-acc-guild-list{
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.7rem;
}


.vc-acc-tier,
.vc-acc-guild{
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.85rem 0.95rem;
  border-radius: 0.9rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
}


.vc-acc-tier__ico,
.vc-acc-plan__ico{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 0.75rem;
  background: rgba(212, 168, 136, 0.16);
  color: #f0d2b4;
  flex: 0 0 auto;
}


.vc-acc-plan__guild-img{
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 0.8rem;
  object-fit: cover;
  flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.06);
}


.vc-acc-tier__copy,
.vc-acc-guild__copy{
  min-width: 0;
  flex: 1 1 auto;
  display: grid;
  gap: 0.15rem;
}


.vc-acc-tier__copy strong,
.vc-acc-guild__copy strong{
  color: #fff;
  font-size: 0.95rem;
}


.vc-acc-tier__copy span,
.vc-acc-guild__copy span{
  color: rgba(201, 183, 166, 0.82);
  font-size: 0.8rem;
}


.vc-acc-plan__head{
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
  min-height: 3.35rem;
}


.vc-acc-plan__head > div{
  min-width: 0;
  flex: 1 1 auto;
}


.vc-acc-plan__title{
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  font-size: 1.15rem;
  line-height: 1.25;
}


.vc-acc-plan__sub{
  margin-top: 0.35rem;
}


.vc-acc-plan__actions{
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  flex: 0 0 auto;
  margin-left: auto;
  align-self: flex-start;
  justify-content: flex-end;
}


.vc-acc-plan__meta{
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
  margin: 1rem 0 0;
  margin-top: auto;
  padding-top: 1rem;
}


.vc-acc-plan__meta--sub{
  grid-template-columns: repeat(2, minmax(0, 1fr));
}


.vc-acc-plan__meta div{
  padding: 0.7rem 0.8rem;
  border-radius: 0.75rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
}


.vc-acc-plan__meta dt{
  margin: 0;
  color: rgba(201, 183, 166, 0.75);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}


.vc-acc-plan__meta dd{
  margin: 0.25rem 0 0;
  color: #fff;
  font-size: 1.05rem;
  font-weight: 800;
}


.vc-acc-guild__link{
  display: flex;
  align-items: center;
  gap: 0.85rem;
  width: 100%;
  color: inherit;
  text-decoration: none;
}


.vc-acc-guild__link:hover{
  color: #f7ecdf;
}


.vc-acc-guild__icon{
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 0.8rem;
  overflow: hidden;
  flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.06);
}


.vc-acc-guild__icon img{
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}


.vc-acc-guild__fallback{
  display: inline-flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  color: #f7ecdf;
}


.vc-acc-empty{
  margin-top: 0.85rem;
  padding: 1rem;
  border-radius: 0.85rem;
  border: 1px dashed rgba(212, 168, 136, 0.28);
  color: rgba(232, 201, 168, 0.8);
}


@keyframes vc-qs-cover-ken{
  0% {
    transform: scale(1.04) translate3d(-1.2%, -0.6%, 0);
  }
  100% {
    transform: scale(1.12) translate3d(1.4%, 0.8%, 0);
  }
}


#tk-tx-list-wrap{
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}


#tk-tx-list-wrap[hidden],
#tk-tx-viewer[hidden],
#tk-tx-intro[hidden],
#tk-tx-viewer-loading[hidden]{
  display: none !important;
}


.vc-tx-topbar__label{
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(247, 236, 223, 0.92);
}


.vc-tx-topbar__home{
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.45rem 0.75rem;
  border-radius: 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  color: rgba(247, 236, 223, 0.88);
  font-size: 0.82rem;
  font-weight: 600;
  text-decoration: none;
  transition: border-color 0.15s, background 0.15s;
}


.vc-tx-topbar__home:hover{
  border-color: rgba(var(--vc-sand-rgb), 0.35);
  background: rgba(var(--vc-mocha-rgb), 0.28);
}


.vc-tx-main{
  min-height: calc(100vh - 8rem);
  display: flex;
  flex-direction: column;
  justify-content: center;
}


.vc-tx-gate{
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.5rem 0 1.5rem;
  animation: vc-tx-gate-in 0.45s ease both;
}


.vc-tx-gate[hidden],
.vc-tx-gate.vc-tx-gate--hidden{
  display: none !important;
}


@keyframes vc-tx-gate-in{
  from {
    opacity: 0;
    transform: translateY(10px);
  }
