.vc-ptr{
  position: fixed;
  left: 50%;
  top: calc(env(safe-area-inset-top, 0px) + 4.85rem);
  z-index: 110120;
  width: 6.1rem;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.38rem;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transform: translate3d(-50%, -5.6rem, 0);
  transition: opacity 0.2s ease, transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}


.vc-ptr.is-on{
  opacity: 1;
  visibility: visible;
  z-index: 110120;
  transform: translate3d(-50%, calc(-5.6rem + var(--vc-ptr-y, 0px)), 0);
  transition: none;
}


.vc-ptr.is-snap{
  opacity: 0;
  visibility: hidden;
  transform: translate3d(-50%, -5.6rem, 0);
}


.vc-ptr.is-refreshing{
  opacity: 1;
  visibility: visible;
  /* confPtrAnim1: sopra sipario boot */
  z-index: 2147483010;
  transform: translate3d(-50%, 0.35rem, 0);
  transition: transform 0.32s cubic-bezier(0.22, 1.15, 0.36, 1), opacity 0.18s ease;
}


.vc-ptr:not(.is-on):not(.is-refreshing) .vc-ptr__disc,
.vc-ptr.is-snap:not(.is-refreshing) .vc-ptr__disc{
  box-shadow: none !important;
  filter: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}


.vc-ptr__disc{
  position: relative;
  width: 3.45rem;
  height: 3.45rem;
  border-radius: 9999px;
  transform: rotate(var(--vc-ptr-rot, 0deg)) scale(var(--vc-ptr-scale, 0.86));
  transform-origin: 50% 50%;
  will-change: transform, opacity, filter;
}


.vc-ptr.is-on .vc-ptr__disc{
  transform: rotate(var(--vc-ptr-rot, 0deg)) scale(var(--vc-ptr-scale, 1));
}


.vc-ptr__rotor{
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  background:
    radial-gradient(circle at 50% 50%, transparent 0 0.42rem, #1a120e 0.42rem 0.58rem, transparent 0.59rem),
    repeating-radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.06) 0 1px, transparent 1px 3px),
    radial-gradient(circle at 32% 28%, rgba(255, 255, 255, 0.16), transparent 42%),
    radial-gradient(circle at 50% 50%, #2a1c16 0 38%, #120c0a 62%, #070504 100%);
  box-shadow:
    0 8px 22px rgba(0, 0, 0, 0.42),
    0 0 0 1px rgba(212, 168, 136, 0.28),
    0 0 18px rgba(212, 168, 136, 0.16);
  transform-origin: 50% 50%;
  will-change: transform, box-shadow;
}


.vc-ptr.is-armed .vc-ptr__rotor{
  box-shadow:
    0 10px 26px rgba(0, 0, 0, 0.46),
    0 0 0 1px rgba(212, 168, 136, 0.55),
    0 0 28px rgba(212, 168, 136, 0.42);
}


.vc-ptr__label{
  position: absolute;
  inset: 28%;
  border-radius: 9999px;
  background:
    radial-gradient(circle at 38% 32%, rgba(255, 244, 232, 0.55), transparent 46%),
    linear-gradient(160deg, #ead4c0 0%, #d4a888 48%, #6f4e37 100%);
  box-shadow: inset 0 0 0 1px rgba(80, 48, 28, 0.28);
}


.vc-ptr__hole{
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0.42rem;
  height: 0.42rem;
  margin: -0.21rem 0 0 -0.21rem;
  border-radius: 9999px;
  background: #0b0705;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12);
}


.vc-ptr__hint{
  margin: 0;
  max-width: 9.5rem;
  color: rgba(247, 239, 230, 0.82);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-align: center;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.55);
  opacity: 0.72;
}


.vc-ptr.is-armed .vc-ptr__hint{
  opacity: 1;
  color: #ead4c0;
}


.vc-ptr.is-refreshing .vc-ptr__disc{
  /* ptrVinylSmooth1: pop senza blur */
  animation: vc-ptr-pop 0.42s cubic-bezier(0.22, 1.2, 0.36, 1) both;
  transform: none;
}


.vc-ptr.is-refreshing .vc-ptr__rotor{
  /* ptrVinylSmooth1: solo spin — no glow box-shadow (frame lag) */
  -webkit-animation: vc-ptr-spin 0.85s linear infinite;
  animation: vc-ptr-spin 0.85s linear infinite;
}


.vc-ptr.is-refreshing .vc-ptr__hint{
  animation: vc-ptr-hint-in 0.28s ease 0.08s both;
}


@keyframes vc-ptr-pop{
  0% {
    opacity: 0.4;
    transform: translate3d(0, -1.4rem, 0) scale(0.55);
  }
  70% {
    opacity: 1;
    transform: translate3d(0, 0.1rem, 0) scale(1.04);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}


@keyframes vc-ptr-spin{
  from {
    -webkit-transform: rotate(0deg);
    transform: rotate(0deg);
  }
  to {
    -webkit-transform: rotate(360deg);
    transform: rotate(360deg);
  }
}


@keyframes vc-ptr-glow{
  0%,
  100% {
    box-shadow:
      0 10px 26px rgba(0, 0, 0, 0.46),
      0 0 0 1px rgba(212, 168, 136, 0.4),
      0 0 18px rgba(212, 168, 136, 0.28);
  }
  50% {
    box-shadow:
      0 12px 32px rgba(0, 0, 0, 0.5),
      0 0 0 1px rgba(236, 205, 176, 0.72),
      0 0 34px rgba(212, 168, 136, 0.55);
  }
}


@keyframes vc-ptr-hint-in{
  from {
    opacity: 0;
    transform: translateY(0.35rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}


