.vc-premium-footer{
  position: relative;
  z-index: 10;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  padding: 1.5rem clamp(0.75rem, 2vw, 1.5rem) 0;
  border: 0 !important;
  background: transparent !important;
  overflow: hidden;
}


.vc-premium-footer__card{
  width: 100%;
  max-width: none;
  margin: 0 auto;
}


.vc-premium-footer__outer{
  overflow: hidden;
  border: 1px solid rgba(var(--vc-sand-rgb), 0.28);
  /* footerCorners1 → softLook1g: square footer */
  border-radius: 0;
  background:
    radial-gradient(120% 120% at 14% 0%, rgba(212, 168, 136, 0.18), transparent 54%),
    linear-gradient(145deg, rgba(52, 35, 24, 0.96), rgba(24, 16, 11, 0.98));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 22px 70px rgba(0, 0, 0, 0.34);
}


.vc-premium-footer__inner{
  margin: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}


.vc-premium-footer__grid{
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  padding: clamp(2rem, 3.8vw, 4rem);
  align-items: start;
}


.vc-premium-footer__navcols{
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2rem 1rem;
  align-items: start;
  min-width: 0;
  width: 100%;
}


.vc-premium-footer__brand{
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.85rem;
  text-align: left;
}


.vc-premium-footer__logo-row{
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 0.625rem;
  text-decoration: none;
}


.vc-premium-footer__logo{
  display: flex;
  width: 2rem;
  height: 2rem;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  overflow: hidden;
  /* footerBrandVinyl1: icona server/vinile (no foglia, no caffè) */
  background: #140f0c;
  box-shadow: inset 0 0 0 1px rgba(245, 214, 183, 0.28);
}


.vc-premium-footer__logo-img,
.vc-premium-footer__logo img{
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 8px;
}


.vc-premium-footer__wordmark{
  color: #ead6bb;
  font-size: clamp(1.25rem, 4vw, 1.625rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0;
}


.vc-premium-footer__desc{
  margin: 0;
  max-width: min(28rem, 100%);
  width: 100%;
  color: rgba(234, 214, 187, 0.78) !important;
  font-size: 0.95rem;
  font-weight: 400;
  line-height: 1.55;
  text-align: left !important;
  align-self: stretch;
}


.vc-premium-footer__socials{
  display: flex;
  align-items: center;
  gap: 0.75rem;
}


.vc-premium-footer__social{
  display: flex;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(var(--vc-sand-rgb), 0.18);
  border-radius: 0.75rem;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.025));
  color: rgba(234, 214, 187, 0.94);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 10px 24px rgba(0, 0, 0, 0.18);
  transition:
    background 0.16s ease,
    color 0.16s ease,
    transform 0.16s ease,
    border-color 0.16s ease;
}


.vc-premium-footer__social:hover{
  border-color: rgba(212, 168, 136, 0.45);
  background: linear-gradient(145deg, rgba(212, 168, 136, 0.22), rgba(255, 255, 255, 0.045));
  color: #ead6bb;
}


.vc-premium-footer__social:active{
  transform: scale(0.95);
}


